        if char.isalpha():
            # Swap case
            swapped = char.swapcase()
            # Check if it's a vowel
            if swapped in vowels:
                # Replace with the letter two places ahead
                # Handle both lowercase and uppercase
                if swapped.islower():
                    new_char = chr(ord(swapped) + 2)
                else:
                    new_char = chr(ord(swapped) - 2)
