def minPath(grid, k):
    from heapq import heappush, heappop

    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (current_value, x, y, path, path_value)
    heap = []
    for i in range(n):
        for j in range(n):
            heappush(heap, (grid[i][j], i, j, [grid[i][j]], grid[i][j]))

    visited = set()

    while heap:
        val, x, y, path, path_val = heappop(heap)
        if len(path) == k:
            return path
        key = (x, y, path_val)
        if key in visited:
            continue
        visited.add(key)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                new_path_val = path_val + grid[nx][ny]
                heappush(heap, (grid[nx][ny], nx, ny, new_path, new_path_val))

def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    sequence = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence.append(1 + i // 2)
        else:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i])
    return sequence

